import{_ as t,H as a,f as i,i as n}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"国庆策划01 | 知识挑战赛：检验一下学习成果吧！","description":"","frontmatter":{},"headers":[{"level":2,"title":"第一题","slug":"第一题","link":"#第一题","children":[]},{"level":2,"title":"第二题","slug":"第二题","link":"#第二题","children":[]}],"relativePath":"计算机基础实战课/国庆策划01｜知识挑战赛：检验一下学习成果吧！.md","filePath":"计算机基础实战课/国庆策划01｜知识挑战赛：检验一下学习成果吧！.md","lastUpdated":1795560006000}'),r={name:"计算机基础实战课/国庆策划01｜知识挑战赛：检验一下学习成果吧！.md"};function s(_,e,l,o,E,p){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="国庆策划01-知识挑战赛-检验一下学习成果吧" tabindex="-1">国庆策划01 | 知识挑战赛：检验一下学习成果吧！ <a class="header-anchor" href="#国庆策划01-知识挑战赛-检验一下学习成果吧" aria-label="Permalink to &quot;国庆策划01 | 知识挑战赛：检验一下学习成果吧！&quot;">​</a></h1><p>你好，我是课程编辑小新。现在还是国庆假期，先祝你假期快乐！</p><p>到现在为止，课程已经更新过半，不知道你的学习进度如何了？是不是还在和前面某节课相互“battle”，或者定了个计划，预备先梳理完前置知识再来学习课程，但忙着忙着就忘了……悠闲的假期，正是你沉下心深度学习，跟上大部队节奏的好机会。</p><p>我和 LMOS 老师商量之后，特意策划了三期加餐内容，作为国庆的特别策划。今天是第一期，我们先做做题，检验一下自己的学习成果，查漏补缺；第二期我会邀请两位课代表分享分享他们的学习方法、经验；第三期我们再公布今天主观题的参考答案。</p><p>接下来，就让我们进入知识挑战赛这个环节吧！点击下面的按钮即可挑战客观题，一共 10 道题目，5 道单选题，5 道多选题，满分 100 分，系统自动评分。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%259B%25BD%25E5%25BA%2586%25E7%25AD%2596%25E5%2588%259201/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%259B%25BD%25E5%25BA%2586%25E7%25AD%2596%25E5%2588%259201/1.png" alt=""></a></p><p>接下来是两道主观题，请听题。</p><h2 id="第一题" tabindex="-1">第一题 <a class="header-anchor" href="#第一题" aria-label="Permalink to &quot;第一题&quot;">​</a></h2><p>在前面课程里，我们一起揭秘了 C 语言编译器的“搬砖”日常，搞清楚了 C 语言会如何处理各种类型变量、各种运算符、流程控制以及由它们组成的函数，并把这些内容加以转换，对应到机器指令。你知道在这个转换过程中，C 编译器为了提高程序的执行性能，会有哪些额外的操作呢？试试概括一下这些操作？</p><h2 id="第二题" tabindex="-1">第二题 <a class="header-anchor" href="#第二题" aria-label="Permalink to &quot;第二题&quot;">​</a></h2><p>在堆与栈的区别和应用这节课中，我们知道了堆与栈区别。同时，我们也清楚了 C 语言的函数的局部变量和返回地址都保存在栈中，如果有人对这栈中数据破坏就会导致安全隐患，例如改写返回地址，使之指向别的恶意程序。那问题来了，请问我们有什么栈保护机制么，可以用你的语言描述一下么？</p><p>期待你的回答，我们下节课见！</p>',12)])])}const d=t(r,[["render",s]]);export{c as __pageData,d as default};
